-- Run as DB owner after 005, with two disposable UUIDs generated by verifier.
-- Metadata-only QRIS fixture: NO QRIS image/payload or real payment is created.
-- All test orders/configuration/storage metadata are rolled back.
begin;
select set_config('test.user_a','__USER_A__',true),set_config('test.user_b','__USER_B__',true);
create function pg_temp.assert_true(ok boolean,label text) returns void language plpgsql as $$ begin if ok is distinct from true then raise exception 'FAIL: %',label; end if; end $$;
create function pg_temp.denied(command text,code text) returns boolean language plpgsql as $$ begin execute command;return false;exception when others then return sqlstate=code;end $$;
select pg_temp.assert_true(current_setting('test.user_a')<>current_setting('test.user_b'),'different users');
select pg_temp.assert_true((select count(*)=2 from auth.users where id in(current_setting('test.user_a')::uuid,current_setting('test.user_b')::uuid)),'registered test accounts');
select pg_temp.assert_true(not exists(select 1 from public.profiles where user_id in(current_setting('test.user_a')::uuid,current_setting('test.user_b')::uuid)),'dedicated accounts without onboarding');
select pg_temp.assert_true(not exists(select 1 from public.admin_users where user_id in(current_setting('test.user_a')::uuid,current_setting('test.user_b')::uuid)),'test users not admins');
select pg_temp.assert_true((select public=false from storage.buckets where id='payment-proofs'),'proof bucket private');
insert into public.products(code,name,type,price_rupiah,duration_days,plan,active) values('test-checkout','TEST ONLY metadata fixture','subscription',9900,30,'plus',false);
select set_config('test.product',(select id::text from public.products where code='test-checkout'),true);
select set_config('request.jwt.claim.sub',current_setting('test.user_a'),true);
set local role authenticated;
select pg_temp.assert_true(pg_temp.denied($q$select public.create_order('test-checkout',gen_random_uuid())$q$,'22023'),'inactive product denied');
select pg_temp.assert_true(pg_temp.denied($q$insert into public.admin_users(user_id) values(auth.uid())$q$,'42501'),'self admin denied');
select pg_temp.assert_true(pg_temp.denied($q$insert into public.entitlements(user_id,plan,starts_at,ends_at,source_order_id) values(auth.uid(),'pro',now(),now()+interval '30 days',gen_random_uuid())$q$,'42501'),'self entitlement denied');
select pg_temp.assert_true(pg_temp.denied($q$update public.products set price_rupiah=1 where id=current_setting('test.product')::uuid$q$,'42501'),'price edit denied');
reset role;
update public.products set active=true where id=current_setting('test.product')::uuid;
-- Product-specific disabled config overrides no settings for test case.
insert into public.payment_settings(product_id,merchant_name,qris_path,enabled) values(current_setting('test.product')::uuid,'TEST ONLY NO MERCHANT','test-no-file.png',true);
set local role authenticated;
select pg_temp.assert_true(pg_temp.denied($q$select public.create_order('test-checkout',gen_random_uuid())$q$,'22023'),'missing QRIS asset denied');
reset role;
insert into storage.objects(bucket_id,name) values('merchant-qris','test-no-file.png');
select set_config('test.request',gen_random_uuid()::text,true);
set local role authenticated;
select set_config('test.order_a',(public.create_order('test-checkout',current_setting('test.request')::uuid)).id::text,true);
select pg_temp.assert_true((public.create_order('test-checkout',current_setting('test.request')::uuid)).id=current_setting('test.order_a')::uuid,'retry order idempotent');
select pg_temp.assert_true((select count(*)=1 from public.orders where product_id=current_setting('test.product')::uuid),'no retry duplicate');
select pg_temp.assert_true((select price_rupiah=9900 and total_rupiah=9900 and duration_days=30 and plan='plus' from public.orders where id=current_setting('test.order_a')::uuid),'catalog snapshot');
select pg_temp.assert_true(pg_temp.denied($q$update public.orders set status='paid',price_rupiah=1,total_rupiah=1 where id=current_setting('test.order_a')::uuid$q$,'42501'),'status/snapshot write denied');
select pg_temp.assert_true(pg_temp.denied($q$insert into public.payment_confirmations(order_id,user_id,reference) values(current_setting('test.order_a')::uuid,auth.uid(),'test')$q$,'42501'),'direct confirmation insert denied');
reset role;
update public.products set price_rupiah=19900,duration_days=60,name='Changed test name' where id=current_setting('test.product')::uuid;
set local role authenticated;
select pg_temp.assert_true((select price_rupiah=9900 and duration_days=30 and product_name='TEST ONLY metadata fixture' from public.orders where id=current_setting('test.order_a')::uuid),'snapshot unchanged by catalog edit');
select pg_temp.assert_true(pg_temp.denied($q$select public.submit_payment_confirmation(current_setting('test.order_a')::uuid,'xx','',null)$q$,'22023'),'reference required');
select pg_temp.assert_true(pg_temp.denied($q$select public.submit_payment_confirmation(current_setting('test.order_a')::uuid,'ref','',current_setting('test.user_b')||'/'||current_setting('test.order_a')||'/fake.png')$q$,'42501'),'other proof rejected');
insert into storage.objects(bucket_id,name,metadata) values('payment-proofs',auth.uid()::text||'/'||current_setting('test.order_a')||'/metadata-proof.png','{"mimetype":"image/png","size":100}');
select set_config('test.proof_a',auth.uid()::text||'/'||current_setting('test.order_a')||'/metadata-proof.png',true);
select pg_temp.assert_true((public.submit_payment_confirmation(current_setting('test.order_a')::uuid,'TEST-REFERENCE','metadata test, no payment',current_setting('test.proof_a'))).status='submitted','confirmation -> submitted');
select pg_temp.assert_true((public.submit_payment_confirmation(current_setting('test.order_a')::uuid,'TEST-REFERENCE','',null)).status='submitted','repeat confirmation idempotent');
select pg_temp.assert_true((select count(*)=1 from public.payment_confirmations where order_id=current_setting('test.order_a')::uuid),'one confirmation');
select pg_temp.assert_true(public.get_entitlement()->>'plan'='free','submitted does not grant Premium');
select pg_temp.assert_true((select count(*)=0 from public.entitlements where source_order_id=current_setting('test.order_a')::uuid),'no entitlement from confirmation');
reset role;
update public.orders set expires_at=now()-interval '1 second' where id=current_setting('test.order_a')::uuid;
select set_config('request.jwt.claim.sub',current_setting('test.user_b'),true);
set local role authenticated;
select set_config('test.order_b',(public.create_order('test-checkout',gen_random_uuid())).id::text,true);
select pg_temp.assert_true((select count(*)=0 from public.orders where id=current_setting('test.order_a')::uuid),'B cannot read A order');
select pg_temp.assert_true((select count(*)=0 from public.payment_confirmations where order_id=current_setting('test.order_a')::uuid),'B cannot read A confirmation');
select pg_temp.assert_true((select count(*)=0 from storage.objects where bucket_id='payment-proofs' and name=current_setting('test.proof_a')),'B cannot read A proof');
select pg_temp.assert_true(pg_temp.denied($q$select public.submit_payment_confirmation(current_setting('test.order_a')::uuid,'FORGED','',null)$q$,'42501'),'B cannot confirm A order');
select pg_temp.assert_true(pg_temp.denied($q$insert into storage.objects(bucket_id,name) values('payment-proofs',current_setting('test.user_a')||'/'||current_setting('test.order_a')||'/forged.png')$q$,'42501'),'B cannot upload to A folder');
reset role;
update public.orders set expires_at=now()-interval '1 second' where id=current_setting('test.order_b')::uuid;
set local role authenticated;
select pg_temp.assert_true((select status='expired' from public.list_my_orders() where id=current_setting('test.order_b')::uuid),'pending expires on read');
select pg_temp.assert_true(pg_temp.denied($q$select public.submit_payment_confirmation(current_setting('test.order_b')::uuid,'EXPIRED','',null)$q$,'22023'),'expired confirmation denied');
reset role;
insert into public.entitlements(user_id,plan,starts_at,ends_at,source_order_id) values
 (current_setting('test.user_a')::uuid,'plus',now()-interval '2 days',now()-interval '1 day',current_setting('test.order_a')::uuid),
 (current_setting('test.user_b')::uuid,'plus',now()-interval '2 days',now()-interval '1 day',current_setting('test.order_b')::uuid);
select set_config('request.jwt.claim.sub',current_setting('test.user_a'),true);
set local role authenticated;
select pg_temp.assert_true((select count(*)=1 from public.entitlements where user_id=auth.uid()),'own entitlement readable');
select pg_temp.assert_true((select count(*)=0 from public.entitlements where user_id=current_setting('test.user_b')::uuid),'other entitlement hidden');
select pg_temp.assert_true((select status='submitted' from public.list_my_orders() where id=current_setting('test.order_a')::uuid),'submitted does not expire');
select pg_temp.assert_true((select count(*)=0 from public.orders where id=current_setting('test.order_b')::uuid),'A cannot read B order');
select pg_temp.assert_true(pg_temp.denied($q$update public.subscriptions set plan='pro',expires_at=now()+interval '365 days' where user_id=auth.uid()$q$,'42501'),'subscription still protected');
reset role;
select 'PASS: checkout assertions; no payment; rollback removes metadata and orders' as result;
rollback;
